{
 "command": "ls var/cache/search/ && head -c 300 var/cache/search/shard-000.json; echo; git status --short var/ ; git check-ignore -v var/cache/search/shard-000.json",
 "description": "Inspect cached shard contents"
}

{
 "command": "python3 scripts/build_search_index.py --clear-cache && cat var/search/index.json",
 "description": "Rebuild index after clearing stale cache"
}

{
 "type": "hazard",
 "summary": "build_search_index.py \"unexpected token in shard-N.json\" means stale cache (tokenizer version mismatch); fix with --clear-cache",
 "content": "If scripts/build_search_index.py fails with `index build failed: unexpected token in shard-000.json`, the shard isn't corrupt. The message is misleading: the cached shards in var/cache/search/ were built with an older tokenizer version (e.g. `\"tokenizer\": 2`), and the script's TOKENIZER constant is now 3. Fix: rerun with `--clear-cache`. That drops the gitignored cache and rebuilds var/search/index.json.",
 "physical": [
  "scripts/build_search_index.py"
 ],
 "invalidated_by": [
  "scripts/build_search_index.py"
 ],
 "epistemic": "observation"
}
